sys_script_include.script:
var HospitalService = Class.create();
HospitalService.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	/**
     * Reference Qualifier for 'service' field on Hospital Service table.
     * Returns active catalog items (sc_cat_item) that belong to the 'Support / Hospital Services' category (sys_id: 9aa10a2ac3112200b12d9f2974d3aefd).
     */
    getServiceRefQual: function(current) {
        var serviceSysids = [];
        var categorySysId = '9aa10a2ac3112200b12d9f2974d3aefd'; // Hospital Services category sys_id

        // sc_cat_item table par query run karo
        var catItemGr = new GlideRecord('sc_cat_item');
        catItemGr.addQuery('active', true);

        // Cat item table me category field ya sc_cat_item_category mapping check hoti hai
        // Standard ServiceNow me sc_cat_item par 'category' reference field hota hai
        catItemGr.addQuery('category', categorySysId);
        catItemGr.query();

        while (catItemGr.next()) {
            serviceSysids.push(catItemGr.getUniqueValue());
        }

        // Final Encoded Query return karo
        if (serviceSysids.length > 0) {
            return 'sys_idIN' + serviceSysids.join(',');
        } else {
            // Agar koi item match na ho toh empty result dikhao
            return 'sys_id=00000000000000000000000000000000';
        }
    },

    type: 'HospitalService'
});
